  Lemma apriv_shadow : forall SP X Y, arng X Y -> X <= Y -> X mod 8 = 0 -> aceil <= SP ->
    (forall A n, In (A, n) LB -> bsep A n X Y) -> (Y <= FSB \/ FSB + AFS_SIZE <= X) -> apriv LB SP (sh X) (sh X + (Y - X) / 8).
