  Lemma apriv_region_hi_sh : forall SP c X Y, 0 <= c < kNumClasses -> RB s c + rg_allocated_user (get_region st c) <= X -> Y <= RB s c + kRegionSize ->
    X <= Y -> X mod 8 = 0 -> aceil <= SP -> apriv LB SP (sh X) (sh X + (Y - X) / 8).
Proof.
